void App_bootloader_check_update(void)
{
    printf("bootloader satrt\n");
    printf("check update\n");
    // 读取更新状态和两个密钥字节。
    uint8_t data[3] = {0};
    int_eeprom_read(CHECK_UPDATE_ADDR, data, 3);

    // 首次只初始化 EEPROM，保留本次启动的默认状态。
    uint16_t key = data[1] << 8 | data[2];
    if (key != BOOT_KEY)
    {
        data[0] = BOOT_UPDATE;
        data[1] = (uint8_t)(BOOT_KEY >> 8);
        data[2] = (uint8_t)BOOT_KEY;
        int_eeprom_write(CHECK_UPDATE_ADDR, data, 3);
        HAL_Delay(10);
    }
    else
    {
        uint32_t primask = __get_PRIMASK();

        // 读取有效状态，同时保留 KEY1 恢复请求。
        __disable_irq();
        if (bootloader_check_update_status != BOOT_RESET)
        {
            bootloader_check_update_status = data[0];
        }
        __set_PRIMASK(primask);
    }
}

static uint8_t App_bootloader_check_meta(void)
{
    // 按块、扇区、页和页内字节地址读取元数据。
    if (int_w25q16_read(APP_META_BLOCK, APP_META_SECTOR, APP_META_PAGE, APP_META_BYTE_ADDR, data, sizeof(data)) != 0)
    {
        return 1;
    }
    w25_app_start_addr = (uint32_t)data[0] | ((uint32_t)data[1] << 8) | ((uint32_t)data[2] << 16) | ((uint32_t)data[3] << 24);
    app_size_bytes = (uint32_t)data[4] | ((uint32_t)data[5] << 8) | ((uint32_t)data[6] << 16) | ((uint32_t)data[7] << 24);

    // BIN 从第 1 个扇区起存放；长度为 (0x0800, 0x78000]，整段 APP 不能超出 W25Q16。
    if ((w25_app_start_addr < APP_W25_START_ADDR_MIN) || (w25_app_start_addr >= W25Q16_SIZE_BYTES) ||
        (app_size_bytes <= 0x0800) || (app_size_bytes > 0x78000) ||
        (app_size_bytes > W25Q16_SIZE_BYTES - w25_app_start_addr))
    {
        printf("APP metadata error: W25=0x%08lX length=%lu\r\n",
               (unsigned long)w25_app_start_addr, (unsigned long)app_size_bytes);
        return 1;
    }

    if (int_w25q16_read_address(w25_app_start_addr, data, sizeof(data)) != 0)
    {
        return 1;
    }

    // 栈顶地址必须位于 SRAM 或 CCM 内，允许指向 RAM 末端。
    if (!(((APP_STACK_PTR > 0x20000000) && (APP_STACK_PTR <= 0x20020000)) ||
          ((APP_STACK_PTR > 0x10000000) && (APP_STACK_PTR <= 0x10010000))))
    {
        printf("APP stack pointer error: 0x%08lX\r\n", (unsigned long)APP_STACK_PTR);
        return 1;
    }

    // 复位入口必须位于搬运后的 APP 范围内。
    if ((APP_RESET_HANDLER < APP_START_ADDR + 8) || (APP_RESET_HANDLER >= APP_START_ADDR + app_size_bytes))
    {
        printf("APP reset handler error: 0x%08lX\r\n", (unsigned long)APP_RESET_HANDLER);
        return 1;
    }

    printf("APP check ok: W25=0x%08lX length=%lu\r\n",
           (unsigned long)w25_app_start_addr, (unsigned long)app_size_bytes);
    return 0;
}

static uint8_t App_bootloader_erase_app_flash(void)
{
    FLASH_EraseInitTypeDef erase;
    uint32_t sector_error;
    uint32_t last_addr = APP_START_ADDR + app_size_bytes - 1;
    uint32_t last_sector;
    HAL_StatusTypeDef status;

    // F407VE 共 512 KiB：扇区 0~3 各 16 KiB，扇区 4 为 64 KiB，扇区 5~7 各 128 KiB。
    if (last_addr < 0x08010000)
    {
        last_sector = (last_addr - 0x08000000) / 0x4000;
    }
    else if (last_addr < 0x08020000)
    {
        last_sector = FLASH_SECTOR_4;
    }
    else
    {
        last_sector = FLASH_SECTOR_5 + (last_addr - 0x08020000) / 0x20000;
    }

    if (HAL_FLASH_Unlock() != HAL_OK)
    {
        return 1;
    }
    erase.TypeErase = FLASH_TYPEERASE_SECTORS;
    erase.Sector = FLASH_SECTOR_2;
    erase.NbSectors = last_sector - FLASH_SECTOR_2 + 1;
    erase.VoltageRange = FLASH_VOLTAGE_RANGE_3;
    status = HAL_FLASHEx_Erase(&erase, &sector_error);
    if ((HAL_FLASH_Lock() != HAL_OK) || (status != HAL_OK))
    {
        return 1;
    }
    return 0;
}

static uint8_t App_bootloader_write_app_flash(void)
{
    static uint8_t buffer[512];
    uint32_t offset = 0;
    uint32_t length;
    uint16_t i;
    uint16_t value;

    // 读取元数据，校验数据。
    if (App_bootloader_check_meta() != 0)
    {
        return 1;
    }

    // 3.1 提前擦除足够的 Flash 空间。
    if (App_bootloader_erase_app_flash() != 0)
    {
        return 1;
    }

    if (HAL_FLASH_Unlock() != HAL_OK)
    {
        return 1;
    }
    // 512 字节可整分所有 Flash 扇区，逐块搬运，不占用整扇区 RAM。
    while (offset < app_size_bytes)
    {
        length = app_size_bytes - offset;
        if (length > sizeof(buffer))
        {
            length = sizeof(buffer);
        }
        if (int_w25q16_read_address(w25_app_start_addr + offset, buffer, (uint16_t)length) != 0)
        {
            // SPI 失败或 BUSY 超时后不写入本块，保留升级标记并交给恢复程序。
            HAL_FLASH_Lock();
            return 1;
        }

        // 最后一块若为奇数长度，补 FF 后按半字写入，不多读 W25Q16。
        if ((length % 2) != 0)
        {
            buffer[length] = 0xFF;
        }
        for (i = 0; i < length; i += 2)
        {
            value = (uint16_t)buffer[i] | ((uint16_t)buffer[i + 1] << 8);
            if (HAL_FLASH_Program(FLASH_TYPEPROGRAM_HALFWORD, APP_START_ADDR + offset + i, value) != HAL_OK)
            {
                HAL_FLASH_Lock();
                return 1;
            }
        }
        offset += length;
    }
    if (HAL_FLASH_Lock() != HAL_OK)
    {
        return 1;
    }
    return 0;
}

void app_update_receive(void)
{
    /* 先判断 BIN 是否结束，避免把已到达 FIFO 的末尾 CRC 拼入 BIN。 */
    if ((uint32_t)(HAL_GetTick() - last_receive_tick) >= APP_UPDATE_RECEIVE_IDLE_MS)
    {
        if (can_rx_len > 0)
        {
            char receive_message[48];
            uint16_t message_length;

            app_update_state = APP_UPDATE_VERIFY;
            message_length = (uint16_t)snprintf(receive_message, sizeof(receive_message), "CAN receive done,len:%lu\r\n", (unsigned long)can_rx_len);
            HAL_UART_Transmit(&huart1, (uint8_t *)receive_message, message_length, 100);
        }
        else
        {
            app_update_state = APP_UPDATE_ERROR;
        }
        return;
    }

    int_can_receive_msg(&can_rx_msg, &can_rx_msg.count);
    if ((can_rx_msg.count > 0) && (can_rx_msg.RxHeader.IDE == CAN_ID_STD) && (can_rx_msg.RxHeader.StdId == APP_UPDATE_DATA_CAN_ID) &&
        (can_rx_msg.RxHeader.RTR == CAN_RTR_DATA) && (can_rx_msg.RxHeader.DLC > 0) && (can_rx_msg.RxHeader.DLC <= sizeof(can_rx_msg.data)))
    {
        /* 超出 5 KiB 时停止本轮，保留已经收到的数据和长度。 */
        if (can_rx_msg.RxHeader.DLC > sizeof(can_rx_buffer) - can_rx_len)
        {
            app_update_state = APP_UPDATE_ERROR;
            return;
        }
        for (uint8_t i = 0; i < can_rx_msg.RxHeader.DLC; i++)
        {
            can_rx_buffer[can_rx_len + i] = can_rx_msg.data[i];
        }
        can_rx_len += can_rx_msg.RxHeader.DLC;
        last_receive_tick = HAL_GetTick();
    }
}

void app_update_check_crc(void)
{
    uint32_t received_crc;
    uint32_t crc_value;

    int_can_receive_msg(&can_rx_msg, &can_rx_msg.count);
    if ((can_rx_msg.count > 0) && (can_rx_msg.RxHeader.IDE == CAN_ID_STD) && (can_rx_msg.RxHeader.StdId == APP_UPDATE_DATA_CAN_ID) &&
        (can_rx_msg.RxHeader.RTR == CAN_RTR_DATA) && (can_rx_msg.RxHeader.DLC == 4))
    {
        /* 末尾单独一帧发送小端 CRC，只对已接收的 BIN 计算校验值。 */
        received_crc = (uint32_t)can_rx_msg.data[0] | ((uint32_t)can_rx_msg.data[1] << 8) |
                       ((uint32_t)can_rx_msg.data[2] << 16) | ((uint32_t)can_rx_msg.data[3] << 24);
        crc_value = app_crc_cal(can_rx_buffer, can_rx_len);
        if (crc_value == received_crc)
        {
            uint8_t success_message[] = "CRC OK\r\n";
            uint8_t store_message[] = "Update save OK\r\n";

            HAL_UART_Transmit(&huart1, success_message, sizeof(success_message) - 1, 100);
            if (app_update_save_image() != 0)
            {
                uint8_t store_error_message[] = "Update save FAIL\r\n";

                app_update_state = APP_UPDATE_ERROR;
                HAL_UART_Transmit(&huart1, store_error_message, sizeof(store_error_message) - 1, 100);
                return;
            }
            app_update_state = APP_UPDATE_DONE;
            HAL_UART_Transmit(&huart1, store_message, sizeof(store_message) - 1, 100);
            return;
        }
    }
    else if ((uint32_t)(HAL_GetTick() - last_receive_tick) < APP_UPDATE_CRC_TIMEOUT_MS)
    {
        return;
    }

    /* CRC 不匹配或最后一帧 BIN 后 2 秒仍无 CRC，清理后允许下一轮命令。 */
    uint8_t error_message[] = "CRC FAIL\r\n";

    HAL_UART_Transmit(&huart1, error_message, sizeof(error_message) - 1, 100);
    memset(can_rx_buffer, 0, sizeof(can_rx_buffer));
    can_rx_len = 0;
    app_update_state = APP_UPDATE_IDLE;
}

static uint32_t bootloader_dma_received_total(void)
{
    uint32_t primask = __get_PRIMASK();
    uint32_t wraps;
    uint32_t remaining;

    /* 同时快照回绕计数和 NDTR，补上已回绕但尚未进入 DMA IRQ 的情况。 */
    __disable_irq();
    wraps = uart1_dma_wrap_count;
    remaining = __HAL_DMA_GET_COUNTER(huart1.hdmarx);
    if (__HAL_DMA_GET_FLAG(huart1.hdmarx, __HAL_DMA_GET_TC_FLAG_INDEX(huart1.hdmarx)) != RESET)
    {
        wraps++;
        remaining = __HAL_DMA_GET_COUNTER(huart1.hdmarx);
        if (remaining == 0)
        {
            remaining = BOOTLOADER_UART_RING_SIZE;
        }
    }
    __set_PRIMASK(primask);
    __DMB();
    return wraps * BOOTLOADER_UART_RING_SIZE + BOOTLOADER_UART_RING_SIZE - remaining;
}

uint8_t Int_bootloader_jump_to_app(uint32_t app_address)
{
    uint32_t app_stack_ptr;
    uint32_t app_reset_handle;
    uint32_t app_end;
    uint32_t index;
    static void (*app_entry)(void);

    if (app_address == RESET_START_ADDR)
    {
        app_end = APP_START_ADDR;
    }
    else if (app_address == APP_START_ADDR)
    {
        app_end = app_addr_end;
    }
    else
    {
        return 1;
    }

    app_stack_ptr = *(volatile uint32_t *)app_address;
    app_reset_handle = *(volatile uint32_t *)(app_address + APP_RESET_VECTOR_OFFSET);
    // F407 的 SRAM 为 128 KiB，CCM 为 64 KiB；栈顶允许等于区域末端。
    if (((app_stack_ptr & APP_STACK_ALIGN_MASK) != 0) ||
        !(((app_stack_ptr > stack_addr_start) && (app_stack_ptr <= SRAM_END_ADDR)) ||
          ((app_stack_ptr > CCM_START_ADDR) && (app_stack_ptr <= CCM_END_ADDR))))
    {
        printf("Error: Invalid stack pointer in application!\r\n");
        return 1;
    }
    // 入口必须在所选分区的向量字之后，并使用 Thumb 状态。
    if (((app_reset_handle & APP_RESET_THUMB_MASK) == 0) ||
        (app_reset_handle < app_address + APP_VECTOR_HEADER_SIZE_BYTES) || (app_reset_handle >= app_end))
    {
        printf("Error: Invalid reset handler in application!\r\n");
        return 1;
    }
    __disable_irq();
    // HAL 复位外设，同时停止 DMA；清除旧中断，交给目标程序重新初始化。
    HAL_DeInit();
    SysTick->CTRL = 0;
    SysTick->LOAD = 0;
    SysTick->VAL = 0;

    for (index = 0; index < 8; index++)
    {
        NVIC->ICER[index] = 0xFFFFFFFF;
        NVIC->ICPR[index] = 0xFFFFFFFF;
    }
    SCB->ICSR = SCB_ICSR_PENDSTCLR_Msk | SCB_ICSR_PENDSVCLR_Msk;
    SCB->VTOR = app_address;
    __DSB();
    __ISB();

    // 静态函数指针不放在当前栈中，切换 MSP 后直接调用目标入口。
    app_entry = (void (*)(void))app_reset_handle;
    // 现有 APP 和恢复程序均在入口处重新开启全局中断。
    __set_MSP(app_stack_ptr);
    app_entry();

    // 目标入口不应返回，避免使用新栈退出当前函数。
    while (1)
    {
    }
}

        //根据MPU6050获取欧拉角
        app_flight_get_euler_angle();

        // 偏航零漂抑制: 偏航只有陀螺仪积分、无绝对参考，残余零偏会被积分放大。
        // IDLE(未解锁、电机停转)且三轴角速度均很小(约<3°/s)时，先累积100次读数
        // 取平均(抵消静止噪声)，再把平均残余增量累加进陀螺仪零点，收敛后yaw不再漂移。
        // 用户手持转动(角速度大)立即复位重来，不会误校准。
        if (flight_state == IDLE)
        {
            static uint8_t still_cnt = 0;
            static int32_t trim_sum_x = 0, trim_sum_y = 0, trim_sum_z = 0;
            static uint16_t trim_cnt = 0;
            if (abs(accel_gyro_data.Gyro.Gyro_x) < 50 &&
                abs(accel_gyro_data.Gyro.Gyro_y) < 50 &&
                abs(accel_gyro_data.Gyro.Gyro_z) < 50)
            {
                if (still_cnt < 250) still_cnt++;
                if (still_cnt >= 250) // 静止稳定约1s后开始累积平均
                {
                    trim_sum_x += accel_gyro_data.Gyro.Gyro_x;
                    trim_sum_y += accel_gyro_data.Gyro.Gyro_y;
                    trim_sum_z += accel_gyro_data.Gyro.Gyro_z;
                    trim_cnt++;
                    if (trim_cnt >= 100) // 100次×2ms≈0.2s平均一次
                    {
                        my_mpu6050_gyro_trim((int16_t)(trim_sum_x / 100),
                                             (int16_t)(trim_sum_y / 100),
                                             (int16_t)(trim_sum_z / 100));
                        trim_sum_x = trim_sum_y = trim_sum_z = 0;
                        trim_cnt = 0;
                    }
                }
            }
            else
            {
                still_cnt = 0;
                trim_sum_x = trim_sum_y = trim_sum_z = 0;
                trim_cnt = 0;
            }
        }
        remote_data remote_snapshot = remote_data_receive;
        // 仅在飞行状态且油门足够时才运行PID，防止地面振动导致积分饱和
        if ((flight_state == NORMAL || flight_state == FIX_HEIGHT)
            && remote_snapshot.thr >= 50)
        {
            app_flight_pid_process();
        }
        //判断定高状态，进入定高PID
        if(flight_state==FIX_HEIGHT)
        {
            static uint8_t count=0;
            count++;
            if(count>=3)
            {
                app_fixed_height_pid_process();
                count=0;
            }
        }
        //气压计周期采样：I2C1 总线由本任务(飞行任务)独占访问，MPU6050 与 SPL006
        //均在此任务内读写，避免与其他任务竞争总线(原实现用关中断保护，已移除)
        {
            static uint8_t spl_cnt = 0;
            spl_cnt++;
            if (spl_cnt >= 3)
            {
                spl_cnt = 0;
                spl_update_data();
            }
        }
        //根据PID值设置电机速度
        app_flight_motor_process();

        vTaskDelayUntil(&xLastWakeTime, flight_task_period);
    }
}

//俯仰角PID(外环角度环: PD, 积分不用在角度环避免振荡)
pid_struct pitch_pid={.kp=2.5,.ki=0,.kd=0.3,.integral_limit=5000,
                      .d_lpf_coef=0.5f,.output_limit=120.0f};
//Y轴角速度，对应俯仰角内环PID(角速度环: PID, 积分消除恒定干扰)
pid_struct gyro_y_pid={.kp=1.5,.ki=0.5,.kd=0.18,.integral_limit=500,
                       .d_lpf_coef=0.5f,.output_limit=500.0f};
//横滚角PID
pid_struct roll_pid={.kp=2.5,.ki=0,.kd=0.3,.integral_limit=5000,
                     .d_lpf_coef=0.5f,.output_limit=120.0f};
//X轴角速度，对应横滚角内环PID
pid_struct gyro_x_pid={.kp=1.5,.ki=0.5,.kd=0.18,.integral_limit=500,
                       .d_lpf_coef=0.5f,.output_limit=500.0f};
//偏航角PID
pid_struct yaw_pid={.kp=0.5,.ki=0,.kd=0.5,.integral_limit=5000,
                    .d_lpf_coef=0.5f,.output_limit=120.0f};
//Z轴角速度，对应偏航角内环PID
pid_struct gyro_z_pid={.kp=0.5,.ki=0.5,.kd=0,.integral_limit=500,
                       .d_lpf_coef=0.5f,.output_limit=500.0f};

//定高PID
pid_struct height_pid={.kp=0.3,.ki=0,.kd=0.5,.integral_limit=5000};

void app_flight_pid_process()
{
    // 测量实际控制周期，替代硬编码 PID_Period(0.002)，
    // 消除 I2C/浮点耗时不固定导致的 D/I 项缩放偏差
    static TickType_t s_last_ctrl_tick = 0;
    TickType_t now = xTaskGetTickCount();
    float ctrl_dt = (s_last_ctrl_tick == 0) ? PID_Period
                                           : ((float)(now - s_last_ctrl_tick)) / 1000.0f;
    s_last_ctrl_tick = now;
    if (ctrl_dt < 0.001f) ctrl_dt = 0.001f;
    if (ctrl_dt > 0.05f)  ctrl_dt = 0.05f;

    pitch_pid.dt = ctrl_dt;
    roll_pid.dt  = ctrl_dt;
    yaw_pid.dt   = ctrl_dt;
    gyro_y_pid.dt = ctrl_dt;
    gyro_x_pid.dt = ctrl_dt;
    gyro_z_pid.dt = ctrl_dt;

remote_data remote_snapshot = remote_data_receive;
//俯仰角，需要给目标值和测量值赋值=》如果平稳飞行则外环角度位0，如果遥控则角度等于摇杆的值
//需要把摇杆1000的值进行转换（带死区，消除中位偏移导致的持续漂移）
//叠加 PITCH_TRIM_DEG 俯仰配平角，抵消桨盘面机械前倾造成的持续前漂
pitch_pid.desire=app_stick_to_angle(remote_snapshot.pit) + PITCH_TRIM_DEG;
//外环的测量值为当前的俯仰角
pitch_pid.measure=euler_angle.pitch;
//内环的测量值为当前的俯仰角角速度
gyro_y_pid.measure=(accel_gyro_data.Gyro.Gyro_y*2000.0/32767.0);
//进行串级PID计算
com_pid_calc_chain(&pitch_pid,&gyro_y_pid);

//横滚角的PID计算
//需要把摇杆1000的值进行转换,横滚角目标值（带死区）
//叠加 ROLL_TRIM_DEG 横滚配平角，抵消桨盘面机械侧倾造成的持续横漂
roll_pid.desire=app_stick_to_angle(remote_snapshot.roll) + ROLL_TRIM_DEG;
//外环的测量值为当前的横滚角
roll_pid.measure=euler_angle.roll;
//内环的测量值为当前的横滚角角速度
gyro_x_pid.measure=(accel_gyro_data.Gyro.Gyro_x*2000.0/32767.0);
//进行串级PID计算
com_pid_calc_chain(&roll_pid,&gyro_x_pid);

//偏航角的PID计算
//需要把摇杆1000的值进行转换,偏航角目标值（带死区）
yaw_pid.desire=app_stick_to_angle(remote_snapshot.yaw);
//外环的测量值为当前的偏航角
yaw_pid.measure=euler_angle.yaw;
//内环的测量值为当前的偏航角角速度
gyro_z_pid.measure=(accel_gyro_data.Gyro.Gyro_z*2000.0/32767.0);
//进行串级PID计算
com_pid_calc_chain(&yaw_pid,&gyro_z_pid);
}

void app_flight_motor_process()
{
    remote_data remote_snapshot = remote_data_receive;
    if (remote_snapshot.shutdown == 1)
    {
        motor_left_down.speed = 0;
        motor_right_down.speed = 0;
        motor_left_top.speed = 0;
        motor_right_top.speed = 0;
    }
    else
    {
    switch (flight_state)
    {
    case IDLE://加锁，让一开始上电电机速度为0
        motor_left_down.speed = 0;
        motor_right_down.speed = 0;
        motor_left_top.speed = 0;
        motor_right_top.speed = 0;
        break;
        case NORMAL:
        {
        int16_t thr = remote_snapshot.thr;
        float pitch_out = gyro_y_pid.output;
        float roll_out = gyro_x_pid.output;
        // 偏航符号修正: 实机桨/电机转向与混控假设相反，导致偏航正反馈(起飞后越转越快)。
        // 取反 yaw_out 使偏航通道恢复负反馈；若改后反而不稳，说明问题在电机通道映射。
        float yaw_out = -gyro_z_pid.output;

        // X型混控（布局见 application_freertos_task.c 注释）：
        // +pitch→前电机(TOP)加速 -pitch→后电机加速
        // +roll →右电机加速      -roll →左电机加速
        // +yaw  →对角配对(左上+右下 / 右上+左下)参与
        // MOTOR_TOP_TRIM / MOTOR_LEFT/RIGHT_TOP_TRIM: 前电机固定补偿(当前清零对照)
        motor_left_top.speed = app_flight_limit_motor_speed(thr+pitch_out-roll_out+yaw_out+MOTOR_TOP_TRIM+MOTOR_LEFT_TOP_TRIM);
        motor_right_top.speed = app_flight_limit_motor_speed(thr+pitch_out+roll_out-yaw_out+MOTOR_TOP_TRIM+MOTOR_RIGHT_TOP_TRIM);
        motor_left_down.speed = app_flight_limit_motor_speed(thr-pitch_out-roll_out-yaw_out);
        motor_right_down.speed = app_flight_limit_motor_speed(thr-pitch_out+roll_out+yaw_out);
        }
        break;
        case FIX_HEIGHT:
        //在定高状态下定高的PID作用
        {
        int16_t thr = remote_snapshot.thr;
        float pitch_out = gyro_y_pid.output;
        float roll_out = gyro_x_pid.output;
        // 偏航符号修正: 与NORMAL模式一致，取反yaw_out保持负反馈
        float yaw_out = -gyro_z_pid.output;

        // 定高混控同样叠加 MOTOR_TOP_TRIM 与左/右前额外补偿
        motor_left_top.speed = app_flight_limit_motor_speed(thr+pitch_out-roll_out+yaw_out+height_pid.output+MOTOR_TOP_TRIM+MOTOR_LEFT_TOP_TRIM);
        motor_right_top.speed = app_flight_limit_motor_speed(thr + pitch_out + roll_out - yaw_out + height_pid.output + MOTOR_TOP_TRIM + MOTOR_RIGHT_TOP_TRIM);
        motor_left_down.speed = app_flight_limit_motor_speed(thr - pitch_out - roll_out - yaw_out + height_pid.output);
        motor_right_down.speed = app_flight_limit_motor_speed(thr - pitch_out + roll_out + yaw_out + height_pid.output);
        }

uint8_t application_recevie_data(void)
{
    memset(rx_buff, 0, TX_PLOAD_WIDTH);       // 清空缓冲区
    uint8_t res=Int_nRF24L01P_RxPacket(rx_buff) ;
   if(res==0)
   {
      // 修复：故障标志每次回包都按当前状态赋值，退出FAIL后必须回传0，
      // 否则一旦进过FAIL，flight[0]永远为1，遥控端蜂鸣器会一直响
      flight[0] = (flight_state == FAIL) ? 1 : 0;
      // 回传MPU6050欧拉角(放大100倍取整，遥控端OLED显示)：
      // flight[1..2]=pitch  flight[3..4]=roll  flight[5..6]=yaw (高字节在前)
      {
          int16_t p = (int16_t)(euler_angle.pitch * 100.0f);
          int16_t r = (int16_t)(euler_angle.roll  * 100.0f);
          int16_t y = (int16_t)(euler_angle.yaw   * 100.0f);
          flight[1] = (p >> 8) & 0xFF; flight[2] = p & 0xFF;
          flight[3] = (r >> 8) & 0xFF; flight[4] = r & 0xFF;
          flight[5] = (y >> 8) & 0xFF; flight[6] = y & 0xFF;
      }
      uint16_t count=5; // 修复：回包重试上限从500改为5，防止阻塞接收任务数秒导致遥控被判失联
      Int_nRF24L01P_TX_Mode(); // 切换发送模式
      while(Int_nRF24L01P_TxPacket(flight)==1&&count--); // 发送数据，直到发送成功
      {}
     Int_nRF24L01P_RX_Mode(); // 切换回接收模式
   }
    // 帧头校验
    if (rx_buff[0] != FRAME_HEADER1 || rx_buff[1] != FRAME_HEADER2 || rx_buff[2] != FRAME_HEADER3)
    {
        return 1; // 返回1表示接收失败
    }
    // 帧尾校验
    uint32_t sum = 0;
    uint32_t sum_receive = 0;
    for (int i = 0; i < TX_PLOAD_WIDTH - 4; i++)
    {
        sum += rx_buff[i];
    }
    // 高位在前
    sum_receive = rx_buff[TX_PLOAD_WIDTH - 4] << 24 | rx_buff[TX_PLOAD_WIDTH - 3] << 16 | rx_buff[TX_PLOAD_WIDTH - 2] << 8 | rx_buff[TX_PLOAD_WIDTH - 1];

    if (sum != sum_receive)
    {
        return 1; // 返回1表示接收失败
    }
    remote_data_receive.thr = (rx_buff[3] << 8) | rx_buff[4];
    remote_data_receive.yaw = (rx_buff[5] << 8) | rx_buff[6];
    remote_data_receive.pit = (rx_buff[7] << 8) | rx_buff[8];
    remote_data_receive.roll = (rx_buff[9] << 8) | rx_buff[10];
    if (rx_buff[11] == 1)
    {
        remote_data_receive.shutdown = !remote_data_receive.shutdown;
    }
    remote_data_receive.fix_height = rx_buff[12];

    //debug_printf(":%d,%d,%d,%d,%d,%d\n", remote_data_receive.yaw, remote_data_receive.thr, remote_data_receive.roll, remote_data_receive.pit, remote_data_receive.shutdown, remote_data_receive.fix_height);
    return 0; // 返回0表示接收成功
}

void application_process_connect_state(uint8_t res)
{
    // 如果返回值为0，表示接收成功，更新连接状态为已连接,此处使用的全局变量只有当前一个地方会修改，所以不需要使用互斥锁等机制来保护
    if (res == 0)
    {
        remote_state = REMOTE_CONNECTED;
        retry_count = 0; // 接收成功，重置重试次数
    }
    else if (res == 1) // 如果返回值为1，表示接收失败，更新连接状态为未连接
    {
        retry_count++;                      // 增加重试次数
        if (retry_count >= MAX_RETRY_COUNT) // 如果重试次数超过最大值，认为连接断开
        {
            remote_state = REMOTE_DISCONNECTED;
            flight_state = FAIL; // 连接断开时将飞行状态设置为IDLE
            retry_count = 0;     // 重置重试次数
        }
    }
}

void application_transmit_data(void)
{
     //使用nRF24L01P进行遥控数据的发送
    //1.先进入发送
    Int_nRF24L01P_TX_Mode();
    uint32_t sum=0;
    //2.发送数据,保证数据唯一性和可靠性,1.帧头检验2.帧尾检验3.重发机制
    //数据本身10字节，帧头检验3字节，帧尾检验和4字节
    transmit_buf[0] = FRAME_HEADER1;
    transmit_buf[1] = FRAME_HEADER2;
    transmit_buf[2] = FRAME_HEADER3;
    // 与写方(摇杆/按键任务)共用 joystick_mutex: 锁内一次性整拷快照并清零命令位
    // (取代原先的关中断临界区),保证整帧数据来自同一次提交;
    // 打包/校验/收发等耗时操作全部在锁外进行
    xSemaphoreTake(joystick_mutex, portMAX_DELAY);
    remote_data local = remote_data_value; // 整拷快照
    remote_data_value.shutdown = 0;        // 发送完成后清零，避免持续发送同一个关机命令
    remote_data_value.fix_high = 0;        // 发送完成后重置定高开关状态
    xSemaphoreGive(joystick_mutex);

    //高8位在前
    transmit_buf[3] = (local.thr >> 8) & 0xFF;
    transmit_buf[4] = local.thr & 0xFF;
    transmit_buf[5] = (local.yaw >> 8) & 0xFF;
    transmit_buf[6] = local.yaw & 0xFF;
    transmit_buf[7] = (local.pit >> 8) & 0xFF;
    transmit_buf[8] = local.pit & 0xFF;
    transmit_buf[9] = (local.rol >> 8) & 0xFF;
    transmit_buf[10] = local.rol & 0xFF;
    transmit_buf[11] = local.shutdown; // 关机切换命令
    transmit_buf[12] = local.fix_high; // 定高开关

    for(int i=0;i<TX_PLOAD_WIDTH-4;i++)
    {
        sum+=transmit_buf[i];
    }
    //帧尾校验帧，高位在前
    transmit_buf[TX_PLOAD_WIDTH-4] = (sum >> 24) & 0xFF;
    transmit_buf[TX_PLOAD_WIDTH-3] = (sum >> 16) & 0xFF;
    transmit_buf[TX_PLOAD_WIDTH-2] = (sum >> 8) & 0xFF;
    transmit_buf[TX_PLOAD_WIDTH-1] = sum & 0xFF;

    //debug_printf(":%d,%d,%d,%d,%d,%d\n", remote_data_value.yaw, remote_data_value.thr, remote_data_value.rol, remote_data_value.pit, remote_data_value.shutdown, remote_data_value.fix_high);
    uint8_t res=Int_nRF24L01P_TxPacket(transmit_buf);

void process_joystick_data(void)
{
    //同一个全局变量，摇杆和按键都使用这个变量，为了防止故障需要进入临界区
    //taskENTER_CRITICAL();
    xSemaphoreTake(joystick_mutex, portMAX_DELAY); // 获取互斥锁，等待直到可用
    Joystick_GetValue(&joystick_value);
    // 把ADC数据的范围和极性转换为有效控制信号,摇杆范围是0-1000
    joystick_value.thr = joystick_value.thr * 1000 / 4095;
    joystick_value.yaw = joystick_value.yaw * 1000 / 4095;
    joystick_value.pit = joystick_value.pit * 1000 / 4095;
    joystick_value.rol = joystick_value.rol * 1000 / 4095;

    // 零偏修正：应用校准结果，消除摇杆中位偏移(如PIT中位505~520)
    // 否则中位偏移会变成持续的俯仰/横滚/偏航指令，导致飞机匀速往一个方向飘
    joystick_value.thr -= thr_offset;
    joystick_value.yaw -= yaw_offset;
    joystick_value.pit -= pit_offset;
    joystick_value.rol -= rol_offset;
    // 按键微调修正
    joystick_value.pit += key_pit_offset;
    joystick_value.rol += key_rol_offset;

    joystick_value.thr = com_limit(joystick_value.thr, 0, 1000); // 油门范围限制在0-1000
    joystick_value.yaw = com_limit(joystick_value.yaw, 0, 1000); // 航向范围限制在0-1000
    joystick_value.pit = com_limit(joystick_value.pit, 0, 1000); // 俯仰范围限制在0到1000
    joystick_value.rol = com_limit(joystick_value.rol, 0, 1000); // 横滚范围限制在0到1000

    // 将摇杆数据赋值给遥控数据结构体(锁内发布;读方持同一把锁即可读到完整一致的一组值)
    remote_data_value.thr = joystick_value.thr;
    remote_data_value.yaw = joystick_value.yaw;
    remote_data_value.pit = joystick_value.pit;
    remote_data_value.rol = joystick_value.rol;

    xSemaphoreGive(joystick_mutex); // 释放互斥锁

    //debug_printf(":%d,%d,%d,%d\n", joystick_value.yaw, joystick_value.thr, joystick_value.rol, joystick_value.pit);
}

static void app_lvgl_task(void *pvParameters)
{
    HAL_StatusTypeDef status;
    uint8_t rtc_finished = 0;
    uint8_t bt_finished = 0;
    (void)pvParameters;

    /* 硬件拉起 + LVGL 注册 + 建测试界面, 在本任务上下文一次性完成 */
    App_Display_Init();
    lv_refr_now(NULL); /* 先提交首帧；DMA完成中断继续工作，不等待其他模块。 */
    app_diag_boot_set(APP_BOOT_FIRST_FRAME_MS, HAL_GetTick());

    if (xTaskCreate(app_sensor_task, "sensor", APP_SENSOR_TASK_STK, NULL, APP_SENSOR_TASK_PRIO, NULL) != pdPASS)
    {
        Error_Handler(); /* FreeRTOS 堆不足 */
    }

    /* 两种启动等待由本任务分阶段推进，sensor可在等待期间独立初始化/采集。 */
    app_diag_boot_set(APP_BOOT_RTC_BEGIN_MS, HAL_GetTick());
    watch_rtc_init_begin();
    app_diag_boot_set(APP_BOOT_BT_BEGIN_MS, HAL_GetTick());
    kt6368a_init_begin();

    for (;;)
    {
        app_diag_task_begin(APP_DIAG_LVGL);
        if (rtc_finished == 0)
        {
            status = watch_rtc_init_service();
            if (watch_rtc_init_is_pending() == 0)
            {
                rtc_finished = 1;
                app_diag_boot_set(APP_BOOT_RTC_END_MS, HAL_GetTick());
                app_diag_boot_set(APP_BOOT_RTC_RESULT, (uint32_t)status);
            }
        }
        if (bt_finished == 0)
        {
            status = kt6368a_init_service();
            if (kt6368a_init_is_pending() == 0)
            {
                bt_finished = 1;
                app_diag_boot_set(APP_BOOT_BT_END_MS, HAL_GetTick());
                app_diag_boot_set(APP_BOOT_BT_RESULT, (uint32_t)status);
            }
        }
        App_Display_Service(); /* 锁 → lv_timer_handler → 解锁 */
        app_diag_service();
        app_diag_task_end(APP_DIAG_LVGL, APP_LVGL_TASK_PERIOD);
        vTaskDelay(pdMS_TO_TICKS(APP_LVGL_TASK_PERIOD));
    }
}

static void app_sensor_task(void *pvParameters)
{
    TickType_t xLastWakeTime = xTaskGetTickCount();
    mpu6050_cal_state cal_state;
    mpu6050_offset_struct offset;
    app_imu_store_result store_result;
    uint16_t cal_stable, cal_frames;
    uint8_t cal_finished = 0;

    (void)pvParameters;
    app_diag_boot_set(APP_BOOT_SENSOR_BEGIN_MS, HAL_GetTick());

    /* SENSOR总线从初始化到采样均由本任务独占；失败仍进入原有故障处理。 */
    my_i2c_init(MY_I2C_BUS_SENSOR);
    app_diag_sensor_init(APP_DIAG_MPU, my_mpu6050_init());
    app_diag_sensor_init(APP_DIAG_BARO, spl006_init());
    app_diag_sensor_init(APP_DIAG_MAG, lsm303dlhc_mag_init());
    app_diag_sensor_init(APP_DIAG_HEART, em7028_init()); /* 配置为待机，原有服务负责启动采样及照明。 */

    /* 数据锁须在任务上下文创建 (调度器已运行, 见 app_display 同款注释) */
    App_IMU_Init();
    store_result = app_imu_store_load(&offset);
    App_Baro_Init();
    app_heart_init();
    app_battery_init();
    app_battery_service(); /* 首次电池读数在零偏校准等待前发布。 */

    app_aht21_init();
    app_diag_boot_set(APP_BOOT_SENSOR_READY_MS, HAL_GetTick());
    app_diag_boot_set(APP_BOOT_CAL_BEGIN_MS, HAL_GetTick());
    if (store_result == APP_IMU_STORE_OK)
    {
        my_mpu6050_restore_offset(&offset);
        cal_finished = 1;
        app_diag_boot_set(APP_BOOT_CAL_STATE, MPU6050_CAL_RESTORED);
        app_diag_boot_set(APP_BOOT_CAL_END_MS, HAL_GetTick());
        app_diag_boot_set(APP_BOOT_CAL_RESULT, 0);
    }
    else
    {
        /* EEPROM空白/无有效记录时才使用原校准，失败不写入。 */
        my_mpu6050_zero_offset_begin(HAL_GetTick());
        app_diag_boot_set(APP_BOOT_CAL_STATE, MPU6050_CAL_WAIT_STILL);
    }
    xLastWakeTime = xTaskGetTickCount();
    app_diag_boot_set(APP_BOOT_SAMPLING_BEGIN_MS, HAL_GetTick());

    imu_lock();
    if (s_err_streak == 0)
    {
        s_imu_data.raw = raw;
        s_imu_data.pitch_deg = s_euler.pitch;
        s_imu_data.roll_deg = s_euler.roll;
        s_imu_data.yaw_deg = s_euler.yaw;
        s_online = 1;
    }
    else if (s_err_streak >= APP_IMU_OFFLINE_STREAK)
    {
        s_online = 0;
    }
    s_imu_data.mag = s_mag;
    memcpy(s_imu_data.mag_body_uT, mag_body, sizeof(mag_body));
    s_imu_data.mag_online = mag_online;
    s_imu_data.mag_fused = mag_fused;
    s_imu_data.mag_calibrated = s_mag_calibrated;
    s_imu_data.mag_cal_state = s_mag_cal_state;
    s_imu_data.mag_fusion_state = mag_fusion_state;
    s_imu_data.mag_cal_samples = s_mag_cal_samples;
    s_imu_data.mag_persist_state = s_mag_persist_state;
    for (axis = 0; axis < 3; ++axis)
    {
        if (s_mag_cal_samples)
        {
            s_imu_data.mag_cal_span_uT[axis] = s_mag_max[axis] - s_mag_min[axis];
        }
        else
        {
            s_imu_data.mag_cal_span_uT[axis] = 0.0f;
        }
    }
    imu_unlock();

    /* 一次成功校准只保存一次，采样/融合完成后写EEPROM，UI读取不被数据锁阻塞。 */
    if (s_mag_save_pending)
    {
        app_mag_calibration_struct calibration;
        app_mag_store_result result;
        s_mag_save_pending = 0;
        for (axis = 0; axis < 3; ++axis)
        {
            calibration.offset_uT[axis] = s_mag_offset[axis];
            calibration.scale[axis] = s_mag_scale[axis];
        }
        result = app_mag_store_save(&calibration);
        if (result == APP_MAG_STORE_OK)
        {
            s_mag_persist_state = APP_MAG_PERSIST_SAVED;
        }
        else
        {
            s_mag_persist_state = APP_MAG_PERSIST_SAVE_FAILED;
        }
        imu_lock();
        s_imu_data.mag_persist_state = s_mag_persist_state;
        imu_unlock();
    }
}

uint8_t App_IMU_GetSnapshot(app_imu_struct *imu)
{
    uint8_t online;

    if (imu == NULL)
    {
        return 0;
    }

    if (s_imu_mux == NULL)
    {
        memset(imu, 0, sizeof(*imu));
        return 0;
    }
    imu_lock();
    *imu = s_imu_data;
    online = s_online;
    imu_unlock();

void LCD_Color_Fill_DMA(uint16_t xsta, uint16_t ysta, uint16_t xend, uint16_t yend, const uint16_t *color_p)
{
    uint32_t bytes = (uint32_t)(xend - xsta + 1) * (uint32_t)(yend - ysta + 1) * 2;

    LCD_Address_Set(xsta, ysta, xend, yend);

    if (bytes > 0xFFFE)
    { /* F4 HAL Size 为 uint16: 超 64KB 罕见大块, 退回阻塞分片 */
        LCD_Color_Fill(xsta, ysta, xend, yend, color_p);
        if (s_lcd_flush_done_cb != NULL)
        {
            s_lcd_flush_done_cb(); /* 阻塞路径无 DMA 中断, 手动补完成事件 */
        }
        return;
    }
    if (HAL_SPI_Transmit_DMA(&hspi1, (uint8_t *)color_p, (uint16_t)bytes) != HAL_OK)
    {
        Error_Handler();
    }
}

/* DMA 传输完成回调 (HAL_DMA_IRQHandler→SPI_DMATransmitCplt 的下游, DMA2_Stream2 中断上下文)
 * 注意: 只做"等末字节移位完成 + 清残留标志 + 通知", 不调任何 FreeRTOS API。 */
void HAL_SPI_TxCpltCallback(SPI_HandleTypeDef *hspi)
{
    if (hspi->Instance == SPI1)
    {
        while (READ_BIT(hspi->Instance->SR, SPI_SR_BSY) != 0)
        {
        } /* 等末字节移出(~1字节位时间) */
        (void)hspi->Instance->DR; /* 清可能残留的 RXNE/OVR */
        if (s_lcd_flush_done_cb != NULL)
        {
            s_lcd_flush_done_cb();
        }
    }

if (s_start.phase == KT_START_SAVE)
{
    if ((uint32_t)(now - s_start.phase_ms) >= 100U)
    {
        kt6368a_start_next();
    }
    return init_status;
}
if (s_start.phase == KT_START_QUERY)
{
    kt6368a_flush_rx();
    s_start.length = s_start.overflow = 0;
    s_start.rx_errors = ble.rx_errors;
    s_start.rx_dropped = ble.rx_dropped;
    s_start.phase_ms = now;
    status = HAL_UART_Transmit(&huart1, (uint8_t *)queries[s_start.query], (uint16_t)strlen(queries[s_start.query]), 10U);
    if (status != HAL_OK)
    {
        return kt6368a_start_finish(status);
    }
    s_start.phase = KT_START_REPLY;
    return HAL_BUSY;
}
if (ble.rx_errors != s_start.rx_errors || ble.rx_dropped != s_start.rx_dropped)
{
    return kt6368a_start_finish(HAL_ERROR);
}
if ((uint32_t)(now - s_start.phase_ms) >= KT6368A_AT_TIMEOUT_MS)
{
    return kt6368a_start_finish(HAL_TIMEOUT);
}
while (budget-- != 0 && kt6368a_read(&byte, 1) != 0)
{
    if (byte == '\r')
    {
        continue;
    }
    if (byte != '\n')
    {
        if (s_start.length < sizeof(s_start.line) - 1U)
        {
            s_start.line[s_start.length++] = (char)byte;
        }
        else
        {
            s_start.overflow = 1;
        }
        continue;
    }
    if (s_start.overflow != 0)
    {
        return kt6368a_start_finish(HAL_ERROR);
    }
    s_start.line[s_start.length] = '\0';
    s_start.length = 0;
    if (strncmp(s_start.line, "ER+", 3) == 0)
    {
        return kt6368a_start_finish(HAL_ERROR);
    }
    if (strncmp(s_start.line, prefixes[s_start.query], 3) != 0)
    {
        continue;
    }
    target = "01";
    if (s_start.query == 0)
    {
        target = KT6368A_BLE_NAME;
    }
    if (strcmp(s_start.line + 3, target) == 0)
    {
        kt6368a_start_next();
        return init_status;
    }
    if (s_start.verifying != 0)
    {
        return kt6368a_start_finish(HAL_ERROR);
    }

void HAL_UART_RxCpltCallback(UART_HandleTypeDef *huart)
{
    uint16_t next;
    if ((huart != &huart1) || !ble.powered)
    {
        return;
    }
    next = (uint16_t)((ble.rx_head + 1U) % KT6368A_RX_BUFFER_SIZE);
    if (next == ble.rx_tail)
    {
        ble.rx_dropped++;
    }
    else
    {
        ble.rx_buffer[ble.rx_head] = ble.rx_byte;
        __DMB();
        ble.rx_head = next;
    }
    if (HAL_UART_Receive_IT(huart, &ble.rx_byte, 1) != HAL_OK)
    {
        ble.rx_errors++;
    }
}

