/* MEMP_NUM_PBUF: the number of memp struct pbufs. If the application

int32_t eth_chip_init(eth_chip_object_t *pobj)
{
    uint32_t phy_id1;
    uint32_t phy_id2;
    uint32_t regvalue;
    uint32_t tickstart;
    uint32_t addr;

    if (pobj->is_initialized != 0)
    {
        return ETH_CHIP_STATUS_OK;
    }

    if ((pobj->io.init != 0) && (pobj->io.init() < 0))
    {
        return ETH_CHIP_STATUS_ERROR;
    }

    pobj->devaddr = ETH_CHIP_MAX_DEV_ADDR + 1;

    /* 通过 PHY ID 识别 LAN8720A；寄存器 31 的低 5 位不是 PHY 地址。 */
    for (addr = 0; addr <= ETH_CHIP_MAX_DEV_ADDR; addr++)
    {
        if ((pobj->io.readreg(addr, ETH_CHIP_PHYID1, &phy_id1) < 0) ||
            (pobj->io.readreg(addr, ETH_CHIP_PHYID2, &phy_id2) < 0))
        {
            continue;
        }

        if ((phy_id1 == ETH_CHIP_PHYID1_VALUE) && ((phy_id2 & ETH_CHIP_PHYID2_MASK) == ETH_CHIP_PHYID2_VALUE))
        {
            pobj->devaddr = addr;
            break;
        }
    }

    if (pobj->devaddr > ETH_CHIP_MAX_DEV_ADDR)
    {
        return ETH_CHIP_STATUS_ADDRESS_ERROR;
    }

    if (pobj->io.writereg(pobj->devaddr, ETH_CHIP_BCR, ETH_CHIP_BCR_SOFT_RESET) < 0)
    {
        return ETH_CHIP_STATUS_WRITE_ERROR;
    }

    tickstart = (uint32_t)pobj->io.gettick();
    do
    {
        if (pobj->io.readreg(pobj->devaddr, ETH_CHIP_BCR, &regvalue) < 0)
        {
            return ETH_CHIP_STATUS_READ_ERROR;
        }

        if (((uint32_t)pobj->io.gettick() - tickstart) > ETH_CHIP_SW_RESET_TO)
        {
            return ETH_CHIP_STATUS_RESET_TIMEOUT;
        }
    } while ((regvalue & ETH_CHIP_BCR_SOFT_RESET) != 0);

    pobj->is_initialized = 1;
    return ETH_CHIP_STATUS_OK;
}

int32_t eth_chip_get_link_state(eth_chip_object_t *pobj)
{
    uint32_t status;
    uint32_t control;

    /* BSR 的链路位为低电平锁存，连续读两次获取当前状态。 */
    if ((pobj->io.readreg(pobj->devaddr, ETH_CHIP_BSR, &status) < 0) ||
        (pobj->io.readreg(pobj->devaddr, ETH_CHIP_BSR, &status) < 0))
    {
        return ETH_CHIP_STATUS_READ_ERROR;
    }

    if ((status & ETH_CHIP_BSR_LINK_STATUS) == 0)
    {
        return ETH_CHIP_STATUS_LINK_DOWN;
    }

    if (pobj->io.readreg(pobj->devaddr, ETH_CHIP_BCR, &control) < 0)
    {
        return ETH_CHIP_STATUS_READ_ERROR;
    }

    if ((control & ETH_CHIP_BCR_AUTONEGO_EN) == 0)
    {
        if ((control & ETH_CHIP_BCR_SPEED_SELECT) != 0)
        {
            if ((control & ETH_CHIP_BCR_DUPLEX_MODE) != 0)
            {
                return ETH_CHIP_STATUS_100MBITS_FULLDUPLEX;
            }
            return ETH_CHIP_STATUS_100MBITS_HALFDUPLEX;
        }

        if ((control & ETH_CHIP_BCR_DUPLEX_MODE) != 0)
        {
            return ETH_CHIP_STATUS_10MBITS_FULLDUPLEX;
        }
        return ETH_CHIP_STATUS_10MBITS_HALFDUPLEX;
    }

    if (pobj->io.readreg(pobj->devaddr, ETH_CHIP_PHYSCSR, &status) < 0)
    {
        return ETH_CHIP_STATUS_READ_ERROR;
    }

    if ((status & ETH_CHIP_PHYSCSR_AUTONEGO_DONE) == 0)
    {
        return ETH_CHIP_STATUS_AUTONEGO_NOTDONE;
    }

    switch (status & ETH_CHIP_PHYSCSR_HCDSPEED_MASK)
    {
        case ETH_CHIP_PHYSCSR_100M_FULL:
            return ETH_CHIP_STATUS_100MBITS_FULLDUPLEX;
        case ETH_CHIP_PHYSCSR_100M_HALF:
            return ETH_CHIP_STATUS_100MBITS_HALFDUPLEX;
        case ETH_CHIP_PHYSCSR_10M_FULL:
            return ETH_CHIP_STATUS_10MBITS_FULLDUPLEX;
        case ETH_CHIP_PHYSCSR_10M_HALF:
            return ETH_CHIP_STATUS_10MBITS_HALFDUPLEX;
        default:
            return ETH_CHIP_STATUS_AUTONEGO_NOTDONE;
    }
}

static void ethernetif_input(void *argument)
{
    struct netif *netif = (struct netif *)argument;
    struct pbuf *p;
    uint32_t errors;

    for (;;)
    {
        if (xSemaphoreTake(s_rx_semaphore, portMAX_DELAY) == pdTRUE)
        {
            do
            {
                p = NULL;
                if (s_rx_alloc_status == RX_ALLOC_OK)
                {
                    HAL_ETH_ReadData(&g_eth_handler, (void **)&p);
                }

                if (p != NULL)
                {
                    HAL_ETH_GetRxDataErrorCode(&g_eth_handler, &errors);
                    if ((errors & ETH_DMARXDESC_ES) != 0U)
                    {
                        pbuf_free(p);
                    }
                    else if (netif->input(p, netif) != ERR_OK)
                    {
                        pbuf_free(p);
                    }
                }
            } while (p != NULL);
        }
    }
}

void HAL_ETH_RxCpltCallback(ETH_HandleTypeDef *heth)
{
    BaseType_t task_woken = pdFALSE;

    (void)heth;
    if (s_rx_semaphore != NULL)
    {
        if (xSemaphoreGiveFromISR(s_rx_semaphore, &task_woken) == pdTRUE)
        {
            portYIELD_FROM_ISR(task_woken);
        }
    }
}

uint8_t lwip_comm_init(void)
{
    ip4_addr_t ipaddr;
    ip4_addr_t netmask;
    ip4_addr_t gateway;
    struct netif *added_netif;

    lwip_comm_default_ip_set(&g_lwipdev);
    if (!s_tcpip_initialized)
    {
        tcpip_init(NULL, NULL);
        s_tcpip_initialized = 1;
    }

#if LWIP_DHCP
    ip4_addr_set_zero(&ipaddr);
    ip4_addr_set_zero(&netmask);
    ip4_addr_set_zero(&gateway);
#else
    IP4_ADDR(&ipaddr, g_lwipdev.ip[0], g_lwipdev.ip[1], g_lwipdev.ip[2], g_lwipdev.ip[3]);
    IP4_ADDR(&netmask, g_lwipdev.netmask[0], g_lwipdev.netmask[1], g_lwipdev.netmask[2], g_lwipdev.netmask[3]);
    IP4_ADDR(&gateway, g_lwipdev.gateway[0], g_lwipdev.gateway[1], g_lwipdev.gateway[2], g_lwipdev.gateway[3]);
#endif

    LOCK_TCPIP_CORE();
    added_netif = netif_add(&g_lwip_netif, &ipaddr, &netmask, &gateway, NULL, ethernetif_init, tcpip_input);
    if (added_netif == NULL)
    {
        UNLOCK_TCPIP_CORE();
        return 1;
    }

    netif_set_default(&g_lwip_netif);
    netif_set_link_callback(&g_lwip_netif, lwip_link_status_updated);
    netif_set_up(&g_lwip_netif);
    UNLOCK_TCPIP_CORE();

    ethernetif_link_check_state(&g_lwip_netif);

    sys_thread_new("eth_link",
                   lwip_link_thread,
                   &g_lwip_netif,
                   LWIP_LINK_STK_SIZE,
                   LWIP_LINK_TASK_PRIO);

#if LWIP_DHCP
    sys_thread_new("eth_dhcp",
                   lwip_dhcp_thread,
                   &g_lwip_netif,
                   LWIP_DHCP_STK_SIZE,
                   LWIP_DHCP_TASK_PRIO);
#endif

static void lwip_dhcp_process(struct netif *netif)
{
    ip4_addr_t ipaddr;
    ip4_addr_t netmask;
    ip4_addr_t gateway;
    struct dhcp *dhcp;
    uint8_t log_event = 0;

    LOCK_TCPIP_CORE();
    switch (g_lwip_dhcp_state)
    {
        case LWIP_DHCP_START:
            ip4_addr_set_zero(&ipaddr);
            netif_set_addr(netif, &ipaddr, &ipaddr, &ipaddr);
            if (dhcp_start(netif) == ERR_OK)
            {
                g_lwipdev.dhcpstatus = 1;
                g_lwip_dhcp_state = LWIP_DHCP_WAIT_ADDRESS;
                log_event = 1;
            }
            break;

        case LWIP_DHCP_WAIT_ADDRESS:
        case LWIP_DHCP_ADDRESS_ASSIGNED:
            if (dhcp_supplied_address(netif))
            {
                uint8_t newly_assigned = (g_lwip_dhcp_state != LWIP_DHCP_ADDRESS_ASSIGNED);
                g_lwip_dhcp_state = LWIP_DHCP_ADDRESS_ASSIGNED;
                g_lwipdev.dhcpstatus = 2;
                g_lwipdev.ip[0] = ip4_addr1(netif_ip4_addr(netif));
                g_lwipdev.ip[1] = ip4_addr2(netif_ip4_addr(netif));
                g_lwipdev.ip[2] = ip4_addr3(netif_ip4_addr(netif));
                g_lwipdev.ip[3] = ip4_addr4(netif_ip4_addr(netif));
                g_lwipdev.netmask[0] = ip4_addr1(netif_ip4_netmask(netif));
                g_lwipdev.netmask[1] = ip4_addr2(netif_ip4_netmask(netif));
                g_lwipdev.netmask[2] = ip4_addr3(netif_ip4_netmask(netif));
                g_lwipdev.netmask[3] = ip4_addr4(netif_ip4_netmask(netif));
                g_lwipdev.gateway[0] = ip4_addr1(netif_ip4_gw(netif));
                g_lwipdev.gateway[1] = ip4_addr2(netif_ip4_gw(netif));
                g_lwipdev.gateway[2] = ip4_addr3(netif_ip4_gw(netif));
                g_lwipdev.gateway[3] = ip4_addr4(netif_ip4_gw(netif));
                if (newly_assigned)
                {
                    log_event = 2;
                }
            }
            else
            {
                g_lwipdev.dhcpstatus = 1;
                dhcp = netif_dhcp_data(netif);
                if ((dhcp != NULL) && (dhcp->tries > LWIP_MAX_DHCP_TRIES))
                {
                    dhcp_stop(netif);
                    lwip_comm_default_ip_set(&g_lwipdev);
                    IP4_ADDR(&ipaddr, g_lwipdev.ip[0], g_lwipdev.ip[1], g_lwipdev.ip[2], g_lwipdev.ip[3]);
                    IP4_ADDR(&netmask, g_lwipdev.netmask[0], g_lwipdev.netmask[1], g_lwipdev.netmask[2], g_lwipdev.netmask[3]);
                    IP4_ADDR(&gateway, g_lwipdev.gateway[0], g_lwipdev.gateway[1], g_lwipdev.gateway[2], g_lwipdev.gateway[3]);
                    netif_set_addr(netif, &ipaddr, &netmask, &gateway);
                    g_lwipdev.dhcpstatus = 0xFF;
                    g_lwip_dhcp_state = LWIP_DHCP_TIMEOUT;
                    log_event = 3;
                }
            }
            break;

        case LWIP_DHCP_LINK_DOWN:
            dhcp_stop(netif);
            ip4_addr_set_zero(&ipaddr);
            netif_set_addr(netif, &ipaddr, &ipaddr, &ipaddr);
            g_lwipdev.dhcpstatus = 0;
            g_lwip_dhcp_state = LWIP_DHCP_OFF;
            log_event = 4;
            break;

        default:
            break;
    }
    UNLOCK_TCPIP_CORE();

void UART0_Proto_RX_IRQHandler(void)
{
    const uint32_t error_mask =
        DL_UART_MAIN_INTERRUPT_OVERRUN_ERROR |
        DL_UART_MAIN_INTERRUPT_BREAK_ERROR |
        DL_UART_MAIN_INTERRUPT_PARITY_ERROR |
        DL_UART_MAIN_INTERRUPT_FRAMING_ERROR;
    const uint32_t interrupt_mask = DL_UART_MAIN_INTERRUPT_RX | error_mask;
    uint32_t status = DL_UART_Main_getRawInterruptStatus(
        UART0_PROTO_INST, interrupt_mask);

    DL_UART_Main_clearInterruptStatus(
        UART0_PROTO_INST, status & interrupt_mask);

    if ((status & error_mask) != 0U) {
        g_uart0_hw_error_count++;
        g_uart0_rx_reset_pending = true;
    }

    while (!DL_UART_Main_isRXFIFOEmpty(UART0_PROTO_INST)) {
        uint8_t ch = (uint8_t)DL_UART_Main_receiveData(UART0_PROTO_INST);
        uint16_t next = (uint16_t)((g_uart0_rx_head + 1U) & UART0_RX_RING_MASK);

        if (next == g_uart0_rx_tail) {
            g_uart0_rx_overflow_count++;
            g_uart0_rx_reset_pending = true;
        } else {
            g_uart0_rx_ring[g_uart0_rx_head] = ch;
            g_uart0_rx_head = next;
        }
    }
}

static bool uart0_parse_frame(void)
{
    char *start = (char *)g_rx_buf;
    char *end;
    long cx = strtol(start, &end, 10);
    if (end == start || *end != ',') {
        return false;
    }

    start = end + 1;
    long cy = strtol(start, &end, 10);
    if (end == start) {
        return false;
    }

    long angle = 0;
    if (*end == ',') {
        start = end + 1;
        angle = strtol(start, &end, 10);
        if (end == start || *end != '\0'
            || angle < -UART0_ANGLE_MAX || angle > UART0_ANGLE_MAX) {
            return false;
        }
    } else if (*end != '\0') {
        return false;
    }

    bool no_ball = (cx == -1L && cy == -1L);
    bool in_range = (cx >= 0L && cx <= UART0_CX_MAX
                     && cy >= 0L && cy <= UART0_CY_MAX);
    if (!no_ball && !in_range) {
        return false;
    }

    memcpy(g_uart0_data.raw, g_rx_buf, g_rx_idx + 1U);
    g_uart0_data.raw_len = g_rx_idx;
    g_uart0_data.cx = (int16_t)cx;
    g_uart0_data.cy = (int16_t)cy;
    g_uart0_data.angle_mdeg = (int32_t)angle;
    g_uart0_data.valid = in_range;
    g_uart0_data.fresh = true;
    return true;
}

int32_t err_px = g_uart0_data.cx - BAL_CENTER_X;
float abs_err = (float)abs(err_px);
float gs_near = (float)pt->gs_near_px;
/* ratio: 0=完全近区, 1=完全远区, 中间线性插值 */
float ratio;
if (gs_near <= 0.0f) {
    ratio = 1.0f;
} else if (abs_err <= gs_near) {
    ratio = abs_err / gs_near;
} else {
    ratio = 1.0f;
}
float kp_eff = pt->k230_kp_near
             + (pt->k230_kp - pt->k230_kp_near) * ratio;
float kd_eff = pt->k230_kd_near
             + (pt->k230_kd - pt->k230_kd_near) * ratio;

Common_PID_Set(&g_balance_pid, kp_eff, pt->k230_ki, kd_eff);
g_balance_pid.Out_Max = (float)pt->k230_max_angle;

/* 计算平滑球速: 低通滤波 + 限幅防噪声尖峰 */
float cur_vx = 0.0f;
if (s_ball_last_cx >= 0) {
    int32_t dt = (int32_t)(tick_ms - s_ball_last_ms);
    if (dt > 0 && dt < 1000) {
        float raw_vx = (float)(g_uart0_data.cx - s_ball_last_cx)
                     / (float)dt;  /* px/ms */
        if (raw_vx >  BALL_VX_MAX) raw_vx =  BALL_VX_MAX;
        if (raw_vx < -BALL_VX_MAX) raw_vx = -BALL_VX_MAX;
        s_ball_vx_smooth = s_ball_vx_smooth
                         * (1.0f - pt->k230_ff_alpha)
                         + raw_vx * pt->k230_ff_alpha;
        cur_vx = s_ball_vx_smooth;
    }
}
s_ball_last_cx = g_uart0_data.cx;
s_ball_last_ms = tick_ms;

/* PID 用原始坐标算 P+D */
float ang = Common_PID_Calc(&g_balance_pid,
                            (float)g_uart0_data.cx,
                            (float)BAL_CENTER_X,
                            (float)tick_ms);

/* 前馈补偿角: 用有效Kp, 量纲与P项一致 */
float ff_angle = cur_vx * pt->k230_ff_pred_ms * kp_eff;
ang += ff_angle;

    } else {
        /* 球无效: 不立即清零, 连续N帧才认为真丢球.
         * K230的YOLO偶发漏检不该打断PID控制. */
        s_ball_miss_cnt++;
        /* During a short dropout, extrapolate the last position using
         * the filtered ball velocity, then continue the same slew-limited
         * angle command. A hard time limit prevents blind motion. */
        if (s_ball_last_cx >= 0) {
            uint32_t age_ms = (uint32_t)(tick_ms - s_ball_last_ms);
            if (age_ms <= BALL_PREDICT_MAX_MS) {
                const pid_tuning_t *pt_pred = PIDTune_GetParams();
                float pred_cx = (float)s_ball_last_cx
                              + s_ball_vx_smooth * (float)age_ms;
                if (pred_cx < 0.0f) pred_cx = 0.0f;
                if (pred_cx > 800.0f) pred_cx = 800.0f;
                float pred_ang = (pred_cx - (float)BAL_CENTER_X)
                               * pt_pred->k230_kp;
                if (pred_ang > (float)pt_pred->k230_max_angle)
                    pred_ang = (float)pt_pred->k230_max_angle;
                if (pred_ang < -(float)pt_pred->k230_max_angle)
                    pred_ang = -(float)pt_pred->k230_max_angle;
                float d = pred_ang - s_angle_cmd_mdeg;
                if (d > 400.0f) d = 400.0f;
                if (d < -400.0f) d = -400.0f;
                s_angle_cmd_mdeg += d;
                StepperTrack_SetTarget((int32_t)s_angle_cmd_mdeg, true);
            }
        }
        /* Hold the last target through short YOLO dropouts. */
        #undef BALL_MISS_TOLERANCE
        #define BALL_MISS_TOLERANCE 8
        if (s_ball_miss_cnt >= BALL_MISS_TOLERANCE) {
            s_ball_last_cx   = -1;
            s_ball_vx_smooth = 0.0f;
            s_angle_cmd_mdeg = 0.0f;
            Common_PID_Clear(&g_balance_pid);
            StepperTrack_SetTarget(0, false);
        }
        /* 保持期内: 不更新目标, 电机维持上一次角度 */
    }
}

/* ── K230 超时保护 ── */
if (!g_k230_timeout
    && (uint32_t)(tick_ms - g_k230_last_rx_ms) >= K230_TIMEOUT_MS) {
    g_k230_timeout = true;
    StepperTrack_SetTarget(0, false);
}

/* ── 推进步进电机角度跟踪 (内部下发 Emm_V5 串口位置命令) ── */
StepperTrack_Update(tick_ms);

void StepperTrack_Update(uint32_t tick_ms)
{
    /* ── 0. 处理电机回复 (轮询 UART1 RX): 到位 / 故障 ── */
    bool reached, fault;
    EMMV5_RX_Poll();
    EMMV5_RX_GetFlags(&reached, &fault);

    if (fault) {
        /* E2/EE 可能表示参数错误、堵转、过热或过流。锁存故障，禁止自动
         * 解除保护；必须由用户明确重新武装，避免反复清除硬件保护。 */
        g_track.fault = true;
        g_track.valid = false;
        g_track.moving = false;
        g_track.state = TRACK_IDLE;
        g_track.target_angle_mdeg = 0;
        g_track.position_error = 0;
        EMMV5_Stop(EMMV5_DEFAULT_ADDR);
        return;
    }

    if (g_track.fault) {
        return;
    }

    if (reached) {
        /* 上一条位置命令已到位: 精确判定运动完成.
         * (需上位机将电机"控制命令应答"设为 Reached/Both 才有 9F 回复;
         *  否则仍走下方 TRACK_IDLE_MS 超时判定) */
        g_track.moving = false;
        g_track.state  = TRACK_IDLE;
    }

    /* ── 1. 目标角度 → 目标绝对脉冲位置 ── */
    int32_t target_steps = StepperTrack_AngleToSteps(g_track.target_angle_mdeg);

    /* ── 1b. 电机轴脉冲级硬限幅: 从上电零点起, 电机轴不超过 ±TRACK_MAX_PULSES
     * (±22.5°), 保证机械行程 ±25° 内. 无论角度换算误差多大都兜底. ── */
    if (target_steps >  TRACK_MAX_PULSES) target_steps =  TRACK_MAX_PULSES;
    if (target_steps < -TRACK_MAX_PULSES) target_steps = -TRACK_MAX_PULSES;

    /* ── 2. 偏差 = 新目标 - 已命令的目标 (rel=1 绝对坐标基准) ── */
    int32_t delta = target_steps - g_track.target_steps;

    /* ── 2b. 命令节流: 距上次下发不足 TRACK_CMD_MIN_INTERVAL_MS → 跳过本次.
     * 例外: 大偏差(>中偏差阈值)不受节流限制, 保证快速响应. ── */
    if (g_track.moving
        && abs(delta) <= TRACK_MED_DELTA_STEPS
        && (uint32_t)(tick_ms - g_track.last_update_ms) < TRACK_CMD_MIN_INTERVAL_MS) {
        g_track.position_error = delta;
        return;
    }

    /* ── 3. 死区检查: 偏差在死区内 → 不动作 ── */
    if (abs(delta) <= TRACK_DEAD_ZONE_STEPS) {
        /* 自上次下发后经过 TRACK_IDLE_MS 仍未再动 → 认为运动完成 */
        if (g_track.moving
            && (uint32_t)(tick_ms - g_track.last_update_ms) >= TRACK_IDLE_MS) {
            g_track.moving = false;
            g_track.state  = TRACK_IDLE;
        }
        g_track.position_error = delta;
        return;
    }

    /* ── 4. 需要移动 → 按偏差大小分档选速度(RPM)和加速度 ── */
    uint32_t abs_delta = (uint32_t)((delta >= 0) ? delta : -delta);

void EMMV5_Position(uint8_t addr, uint8_t dir, uint16_t vel, uint8_t acc,
                    uint32_t pulses, uint8_t rel)
{
    uint8_t cmd[13] = {
        addr, 0xFD, dir,
        (uint8_t)(vel >> 8), (uint8_t)(vel),
        acc,
        (uint8_t)(pulses >> 24), (uint8_t)(pulses >> 16),
        (uint8_t)(pulses >> 8),  (uint8_t)(pulses),
        rel, 0, 0x6B
    };
    emmv5_send_frame(cmd, sizeof(cmd));
}

void EMMV5_PositionSigned(uint8_t addr, uint16_t vel, uint8_t acc,
                          int32_t signed_pulses, uint8_t rel)
{
    uint8_t dir = (signed_pulses < 0) ? 1U : 0U;
    uint32_t pulses = (signed_pulses < 0)
        ? (uint32_t)(-(int64_t)signed_pulses)
        : (uint32_t)signed_pulses;

    EMMV5_Position(addr, dir, vel, acc, pulses, rel);
}

if (g_emmv5_rx.idx == 2) {
    switch (ch) {
    case 0x36: g_emmv5_rx.expect_len = 8; break;  /* 实时位置 (5.5.13) */
    case 0x31: g_emmv5_rx.expect_len = 5; break;  /* 线性化编码器值 (5.5.7) */
    case 0x3A: g_emmv5_rx.expect_len = 5; break;  /* 电机状态标志 (5.5.15) */
    case 0x3B: g_emmv5_rx.expect_len = 5; break;  /* 回零状态标志 (5.4.4) */
    default:   g_emmv5_rx.expect_len = 0; break;
    }
}

bool complete = false;
if (g_emmv5_rx.expect_len > 0U) {
    /* 固定长度读取帧: 收满即停, 末字节必须是校验 0x6B */
    if (g_emmv5_rx.idx == g_emmv5_rx.expect_len && ch == 0x6B) {
        complete = true;
    }
} else if (ch == 0x6B && g_emmv5_rx.idx >= 3) {
    complete = true;
}

if (complete) {
    /* 完整帧: buf[0]=addr, buf[1]=func, buf[2..]=数据, 末字节=0x6B */
    g_emmv5_rx.frame_cnt++;
    g_emmv5_rx.last_frame_len = g_emmv5_rx.idx;
    for (uint8_t i = 0; i < g_emmv5_rx.idx; i++) {
        g_emmv5_rx.last_frame[i] = g_emmv5_rx.buf[i];
    }
    if (g_rx_frame_cb != NULL) {
        g_rx_frame_cb(g_emmv5_rx.buf, g_emmv5_rx.idx);
    }

    /* 位置读取回复解析 (5.5.13):
     *   [Addr][0x36][符号][位置(4字节大端)][0x6B]
     *   符号: 00=正, 01=负 */
    if (g_emmv5_rx.buf[1] == 0x36 && g_emmv5_rx.idx == 8) {
        bool    neg = (g_emmv5_rx.buf[2] != 0x00);
        int64_t raw = ((int64_t)g_emmv5_rx.buf[3] << 24)
                    | ((int64_t)g_emmv5_rx.buf[4] << 16)
                    | ((int64_t)g_emmv5_rx.buf[5] << 8)
                    |  (int64_t)g_emmv5_rx.buf[6];
        int64_t mdeg;
        if (g_emmv5_rx.fw == EMMV5_FW_X) {
            mdeg = raw * 100;                     /* X: 0.1° → 毫度 */
        } else {
            mdeg = (raw * 360000LL) / 65536LL;    /* Emm: 0-65535 一圈 */
        }
        if (neg) mdeg = -mdeg;
        /* 合理性检查: 上电静止位置应在有限圈数内 (如 ±8 圈);
         * 超出 (如误拼的帧) 判为无效, 避免把垃圾值当位置. */
        if (mdeg >= -EMMV5_POS_MAX_MDEG && mdeg <= EMMV5_POS_MAX_MDEG) {
            g_emmv5_rx.position_mdeg  = (int32_t)mdeg;
            g_emmv5_rx.position_valid = true;
        }
    }

    /* 仅把已知命令的回复当作状态。像 01 00 EE 6B 这样的
     * 错位/格式错误帧不能锁存电机堵转故障，否则会把后续所有
     * 位置命令都屏蔽，表现为“上电但电机无力/不动”。 */
    bool known_reply =
        (g_emmv5_rx.buf[1] == 0xF3) || /* enable */
        (g_emmv5_rx.buf[1] == 0xFD) || /* Emm position */
        (g_emmv5_rx.buf[1] == 0xF6) || /* velocity */
        (g_emmv5_rx.buf[1] == 0xFE) || /* stop */
        (g_emmv5_rx.buf[1] == 0x0E) || /* clear clog */
        (g_emmv5_rx.buf[1] == 0x0A) || /* clear position */
        (g_emmv5_rx.buf[1] == 0x36);   /* read position */
    if (known_reply) {
        switch (g_emmv5_rx.buf[2]) {
        case 0x02: g_emmv5_rx.ack_ok  = true; break;
        case 0x9F: g_emmv5_rx.reached = true; break;
        case 0xE2:
        case 0xEE: g_emmv5_rx.fault   = true; break;
        default:   break;
        }
    }
    g_emmv5_rx.state = 0;
    g_emmv5_rx.idx   = 0;
